package com.lianxibu.site.repository.jobs;
import com.lianxibu.site.domain.jobs.ApiRuntimeTelemetry;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;import java.util.function.LongSupplier;
/** Process-local actual completed events, bounded exact histogram, and a continuous capture lease. */
public final class ProcessApiRuntimeTelemetry implements ApiRuntimeTelemetry.Api {
 private static final long MAX=9007199254740991L;private final Clock clock;private final LongSupplier monotonic;private final Instant born;private final String epoch;private final TreeMap<Long,Bucket> buckets=new TreeMap<>();private boolean active,poisoned;private long generation,lastNanos;private Instant captureStarted,lastClock;
 private static final class Bucket{long requests,errors,locks;boolean invalid;final TreeMap<Long,Long> waits=new TreeMap<>();}
 public ProcessApiRuntimeTelemetry(Clock clock,LongSupplier monotonic,Instant born,String epoch){this.clock=Objects.requireNonNull(clock);this.monotonic=Objects.requireNonNull(monotonic);if(born==null||born.getEpochSecond()<0||born.getNano()%1000!=0||epoch==null||!epoch.matches("[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}"))throw new IllegalArgumentException("native API process identity unavailable");this.born=born;this.epoch=epoch;}
 private static final class Native{static final ProcessApiRuntimeTelemetry INSTANCE=new ProcessApiRuntimeTelemetry(Clock.systemUTC(),System::nanoTime,Instant.ofEpochMilli(java.lang.management.ManagementFactory.getRuntimeMXBean().getStartTime()),UUID.randomUUID().toString());}
 public static ProcessApiRuntimeTelemetry nativeProcess(){return Native.INSTANCE;}
 public final class Capture implements AutoCloseable{private final long identity;private Capture(long id){identity=id;}@Override public void close(){synchronized(ProcessApiRuntimeTelemetry.this){if(generation==identity){active=false;buckets.clear();}}}@Override public String toString(){return "NativeApiCapture[redacted]";}}
 public synchronized Capture openCapture(){if(active)throw new IllegalStateException("native API capture already active");Instant now=clock.instant().truncatedTo(ChronoUnit.MICROS);if(now.getEpochSecond()<0||now.isBefore(born)||generation==Long.MAX_VALUE)throw new IllegalStateException("native API capture unavailable");generation++;captureStarted=lastClock=now;lastNanos=monotonic.getAsLong();poisoned=false;buckets.clear();active=true;return new Capture(generation);}
 private Instant now(){if(!active||poisoned)return null;try{Instant now=clock.instant().truncatedTo(ChronoUnit.MICROS);long nanos=monotonic.getAsLong(),elapsed=Math.subtractExact(nanos,lastNanos),wall=Duration.between(lastClock,now).toNanos();if(now.isBefore(lastClock)||elapsed<0||wall<0||Math.abs(Math.subtractExact(elapsed,wall))>TimeTolerance.NANOS){poisoned=true;return null;}lastClock=now;lastNanos=nanos;return now;}catch(RuntimeException invalid){poisoned=true;return null;}}
 private static final class TimeTolerance{static final long NANOS=2_000_000_000L;}
 private Bucket bucket(Instant now){long minute=now.getEpochSecond()/300*300;buckets.headMap(minute-300,false).clear();return buckets.computeIfAbsent(minute,ignored->new Bucket());}
 /** Completion status only; no URL, token, SQL or personal data is captured. */
 public synchronized void completedHttp(int status){Instant now=now();if(now==null)return;Bucket b=bucket(now);if(status<100||status>599||b.requests==MAX){b.invalid=true;return;}b.requests++;if(status>=500)b.errors++;}
 /** Duration supplied only by the native shared entry instrumentation. */
 public synchronized void completedLockWait(long nanos){Instant now=now();if(now==null)return;Bucket b=bucket(now);if(nanos<0||nanos>MAX||b.locks==MAX||!b.waits.containsKey(nanos)&&b.waits.size()>=65536){b.invalid=true;return;}b.locks++;b.waits.merge(nanos,1L,Long::sum);}
 @Override public synchronized ApiRuntimeTelemetry.Evidence read(){Instant now=now();if(now==null)return null;long end=now.getEpochSecond()/300*300,start=end-300;Instant begin=Instant.ofEpochSecond(start);if(start<0||begin.isBefore(captureStarted)||begin.isBefore(born))return null;buckets.headMap(start,false).clear();Bucket b=buckets.get(start);if(b==null)b=new Bucket();if(b.invalid)return null;long p95=0;if(b.locks>0){long rank=(b.locks*95+99)/100,cumulative=0;for(var entry:b.waits.entrySet()){cumulative+=entry.getValue();if(cumulative>=rank){p95=entry.getKey();break;}}if(cumulative<rank)return null;}try{return new ApiRuntimeTelemetry.Evidence(epoch,born,begin,Instant.ofEpochSecond(end),b.requests,b.errors,b.locks,p95,now);}catch(RuntimeException invalid){return null;}}
 @Override public String toString(){return "ProcessApiRuntimeTelemetry[redacted]";}
}
